-- Positions from LegionCore_world_735.26972_2024_10_23.sql, pinned in the manifest.
-- Legacy phaseMask16384 is NOT copied: native PhaseId follows audited questender stages.
-- Templates, loot, flags and existing custom spawns are preserved. No historical bulk import.
DROP TEMPORARY TABLE IF EXISTS `_1kycore_gilneas_spawns`;
CREATE TEMPORARY TABLE `_1kycore_gilneas_spawns` (`id` BIGINT NOT NULL,`map` BIGINT NOT NULL,`zoneId` BIGINT NOT NULL,`areaId` BIGINT NOT NULL,`position_x` DOUBLE NOT NULL,`position_y` DOUBLE NOT NULL,`position_z` DOUBLE NOT NULL,`orientation` DOUBLE NOT NULL,`guid` BIGINT NOT NULL,`spawnDifficulties` VARCHAR(64) NOT NULL,`phaseUseFlags` BIGINT NOT NULL,`PhaseId` BIGINT NOT NULL,`PhaseGroup` BIGINT NOT NULL,`terrainSwapMap` BIGINT NOT NULL,`rotation0` DOUBLE NOT NULL,`rotation1` DOUBLE NOT NULL,`rotation2` DOUBLE NOT NULL,`rotation3` DOUBLE NOT NULL,`spawntimesecs` BIGINT NOT NULL,`animprogress` BIGINT NOT NULL,`state` BIGINT NOT NULL,`isActive` BIGINT NOT NULL,`ScriptName` VARCHAR(64) NOT NULL,`VerifiedBuild` BIGINT NOT NULL);
DROP TEMPORARY TABLE IF EXISTS `_1kycore_gilneas_spawn_guard`;
CREATE TEMPORARY TABLE `_1kycore_gilneas_spawn_guard` (`id` INT PRIMARY KEY);
-- A conflict raises duplicate-key before any persistent write.
SELECT 1 WHERE EXISTS (
    SELECT 1 FROM `_1kycore_gilneas_spawns` s LEFT JOIN `gameobject_template` t ON t.`entry`=s.`id`
    WHERE t.`entry` IS NULL OR t.`type` NOT IN (3,10)
);
SELECT 1 WHERE EXISTS (
    SELECT 1 FROM `_1kycore_gilneas_spawns` s INNER JOIN `gameobject` g ON g.`guid`=s.`guid`
    WHERE g.`id`<>s.`id` OR g.`map`<>s.`map` OR g.`PhaseId`<>s.`PhaseId` OR g.`PhaseGroup`<>0
        OR ABS(g.`position_x`-s.`position_x`)>0.001 OR ABS(g.`position_y`-s.`position_y`)>0.001
        OR ABS(g.`position_z`-s.`position_z`)>0.001
);
SELECT s.`id`,s.`map`,s.`zoneId`,s.`areaId`,s.`position_x`,s.`position_y`,s.`position_z`,s.`orientation`,s.`guid`,s.`spawnDifficulties`,s.`phaseUseFlags`,s.`PhaseId`,s.`PhaseGroup`,s.`terrainSwapMap`,s.`rotation0`,s.`rotation1`,s.`rotation2`,s.`rotation3`,s.`spawntimesecs`,s.`animprogress`,s.`state`,s.`isActive`,s.`ScriptName`,s.`VerifiedBuild` FROM `_1kycore_gilneas_spawns` s
WHERE NOT EXISTS (SELECT 1 FROM `gameobject` g WHERE g.`guid`=s.`guid`)
    AND NOT EXISTS (SELECT 1 FROM `gameobject` g WHERE g.`id`=s.`id` AND g.`map`=s.`map`
        AND g.`PhaseId`=s.`PhaseId` AND g.`PhaseGroup`=0
        AND ABS(g.`position_x`-s.`position_x`)<0.5 AND ABS(g.`position_y`-s.`position_y`)<0.5
        AND ABS(g.`position_z`-s.`position_z`)<0.5);
DROP TEMPORARY TABLE `_1kycore_gilneas_spawns`;
DROP TEMPORARY TABLE `_1kycore_gilneas_spawn_guard`;
